func _on_animation_finished() -> void:
	var anim := String(sprite.animation)
	match anim:
		"attack1", "attack2", "attack3", "attack4":
			if state != "attack":
				return
			if combo_queued and combo < 4 and is_on_floor():
				combo += 1
				_start_swing("attack%d" % combo)
			else:
				state = "normal"
				combo = 0

func _physics_process(delta: float) -> void:
	age += delta
	var step := SPEED * delta * direction / SUBSTEPS
	for i in range(SUBSTEPS):
		position.x += step
		var tip := global_position + Vector2(6 * direction, 0)
		var body := Rect2(global_position - Vector2(6, 2), Vector2(12, 4))
		for enemy in get_tree().get_nodes_in_group("enemies"):
			if enemy.alive and body.intersects(enemy.hurt_rect()):
				enemy.damage(DAMAGE, global_position.x - 20.0 * direction)
				Audio.play("hit")
				_break()
				return
		if level.is_solid_at(tip):
			_break()
			return
	if age > LIFETIME or global_position.x < -32 or global_position.x > level.width_px + 32:
		queue_free()

if absf(dx) > 3.0 and stun <= 0.0:
	facing = 1 if dx > 0.0 else -1
	visual.scale.x = facing
var chasing: bool = player.is_alive() and absf(dx) < RANGE.x and absf(dy) < RANGE.y
var target := 0.0
if chasing and stun <= 0.0 and absf(dx) > 12.0 and _can_walk(facing):
	target = facing * SPEED
if stun <= 0.0:
	velocity.x = move_toward(velocity.x, target, 420.0 * delta)
elif not _can_walk(signi(int(signf(velocity.x)))):
	velocity.x = 0.0
if cone_cooldown <= 0.0 and player_in(CONE, facing):
	_attack()

if state == "attack":
	velocity = velocity.move_toward(Vector2.ZERO, 400.0 * delta)
	if state_time >= WINDUP and not struck:
		struck = true
		open_attack(STRIKE_BOX, facing, STRIKE)
	if state_time >= WINDUP + 0.27:
		state = "fly"
		sprite.play("fly")
else:
	var desired := Vector2.ZERO
	var chest: Vector2 = player.global_position + Vector2(0, -16)
	var to_player := chest - global_position
	if player.is_alive() and absf(to_player.x) < DETECT and absf(to_player.y) < DETECT:
		desired = to_player.normalized() * SPEED
	else:
		var rest := home + Vector2(0, sin(bob * 2.0) * 5.0)
		desired = ((rest - global_position) * 2.0).limit_length(SPEED * 0.6)
	velocity = velocity.move_toward(desired, STEER * delta)
	if velocity.x > 2.0:
		_face(1)
	elif velocity.x < -2.0:
		_face(-1)
	if cone_cooldown <= 0.0:
		if player_in(CONE, 1):
			_attack(1)
		elif player_in(CONE, -1):
			_attack(-1)

func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		if state == "play" or state == "intro":
			_pause()
		elif state == "paused":
			_resume()
		get_viewport().set_input_as_handled()
	elif event.is_action_pressed("confirm") and state == "hint" and hint_ready:
		_close_hint()
		get_viewport().set_input_as_handled()
	elif event.is_action_pressed("restart") and (state == "paused" or (state == "dead" and game_over_menu.visible)):
		_restart()
		get_viewport().set_input_as_handled()
